import xml.etree.ElementTree as ET

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()

    nodes_dict = {}
    for elem in root.iter():
        nodes_dict[elem.tag] = nodes_dict.get(elem.tag, 0) + 1
    return nodes_dict

def categorize_nodes(nodes_dict):
    categorized_dict = {}
    for key, value in sorted(nodes_dict.items()):
        if value not in categorized_dict:
            categorized_dict[value] = [key]
        else:
            categorized_dict[value].append(key)
    return categorized_dict

def make_catalogue(categorized_dict):
    catalogue = []
    for key in sorted(categorized_dict.keys(), reverse=True):
        for node in categorized_dict[key]:
            catalogue.append(node)
    return catalogue

# change 'your_xml_file.xml' to your actual xml file path
