def nonagonal_number(start, end=None, sum_numbers=False):
    static_dict = {0: 0}
    def nth_nonagonal(num): 
        if num not in static_dict: 
            static_dict[num] = nth_nonagonal(num - 1) + 3*(num - 1) +1
        return static_dict[num]

    def sum_to_n(num):
        seq = [nth_nonagonal(i) for i in range(num+1)]
        return sum(seq)

    # base case for single integer
    if type(start) == int and end == None:
        if start < 1 or start > 1000:
            return "Please provide a number between 1 and 1000"
        if not sum_numbers:
            return nth_nonagonal(start)
        else:
            return sum_to_n(start)

    # if a range is given
    elif type(start) == int and type(end) == int:
        if start < 1 or start > 1000 or end < 1 or end > 1000 or end < start:
            return "Please provide a valid range between 1 and 1000"
        return [nth_nonagonal(num) for num in range(start, end + 1)]

    # if a list is given
    elif type(start) == list:
        return_list = []
        for num in start:
            if num < 1 or num > 1000:
                return_list.append("Please provide a number between 1 and 1000")
            else:
                return_list.append(nth_nonagonal(num))
        return return_list
