class NotPalindromeError(Exception):
    def __init__(self, extra):
        self.extra = extra

def check_palindrome(s):
    s_len = len(s)
    if s_len % 2 == 1:
        first_half, second_half = s[:s_len//2], s[s_len//2+1:]
    else:
        first_half, second_half = s[:s_len//2], s[s_len//2:]
    if first_half == second_half[::-1]:
        return True
    else:
        raise NotPalindromeError(s)

def handle_not_palindrome_error(e):
    print(f'Not a palindrome: {getattr(e, "extra")}')
