def quick_sort(a): 
    if len(a) <= 1: 
        return a 

    lower, equal, greater = [], [], [] 

    pivot = a[len(a) - 1] 

    for i in a: 
        if i < pivot: 
            lower.append(i) 
        elif i == pivot: 
            equal.append(i) 
        else: 
            greater.append(i) 

    return quick_sort(lower) + equal + quick_sort(greater)

def traverseTree(node):
    result = []
    if node is None:
        return []
    else:
        result.append(node.data)
        result += traverseTree(node.left)
        result += traverseTree(node.right)
    return result

