    if (isset($datetime_parts[2])) {
        $timezone = $datetime_parts[2];
    }

    // Format the month as a word (e.g., "January" instead of "01")
    $month_name = date("F", mktime(0, 0, 0, $month, 1));

    // Format the hour as 12-hour format with AM/PM indication
    $ampm = "AM";
    if ($hour >= 12) {
        $ampm = "PM";
        $hour -= 12;
    }
    if ($hour == 0) {
        $hour = 12;
    }

    // Format the timezone as ±hh:mm (if present)
    $timezone_str = "";
    if (!empty($timezone)) {
        $timezone_sign = substr($timezone, 3, 1);
        $timezone_hours = substr($timezone, 4, 2);
        $timezone_minutes = substr($timezone, 7, 2);
