import os
import sys
import shutil

def find_and_execute(start_dir, criteria, action):
    for root, dirs, files in os.walk(start_dir):
        for name in files + dirs:
            item_path = os.path.join(root, name)
            if meets_criteria(item_path, name, criteria):
                perform_action(item_path, action)

def meets_criteria(item_path, name, criteria):
    if 'name' in criteria and name != criteria['name']:
        return False
    if 'type' in criteria:
        if criteria['type'] == 'file' and not os.path.isfile(item_path):
            return False
        if criteria['type'] == 'directory' and not os.path.isdir(item_path):
            return False
    if 'size' in criteria and os.path.getsize(item_path) != criteria['size']:
        return False
    return True

def perform_action(item_path, action):
    if action == 'delete':
        if os.path.isfile(item_path):
            os.remove(item_path)
        else:
            shutil.rmtree(item_path)
    # Add more actions as needed (e.g., move, copy)

if __name__ == "__main__":
    if len(sys.argv) < 4:
        print("Usage: python find_simulator.py <start_dir> <criteria> <action>")
        sys.exit(1)

    start_dir = sys.argv[1]
    criteria = parse_criteria(sys.argv[2])
    action = sys.argv[3]

    find_and_execute(start_dir, criteria, action)
```

