class Successors:
    def __init__(self, succ, init):
        self.succ = succ
        self.next = init

    def next(self):
        item = self.next
        if item is None:
            return None
        self.next = self.succ(item)
        return item

    def peek(self):
        return self.next

    def copy(self):
        return Successors(self.succ, self.next)
