def prime_check(n, i=2): 
    # n is not prime if it is less than 2 or can be divided by i 
    if n <= 2:
        return n == 2
    if n % i == 0:
        return False
    if i * i > n:
        return True
    # check for the next divisor
    return prime_check(n, i + 1)

def convert_to_binary(n):
