from botocore.exceptions import NoCredentialsError

def create_s3_client():
    try:
        s3 = boto3.client('s3')
    except NoCredentialsError:
        print("No AWS credentials found")
        s3 = None
    return s3

def upload_file_to_s3(file_path, bucket_name, object_name=None):
    """Upload a file to an S3 bucket

    :param file_path: File to upload
    :param bucket_name: Bucket to upload to
    :param object_name: S3 object name. If not specified then file name is used
    :return: True if file was uploaded, else False
    """
    s3 = create_s3_client()
    if not s3:
        return False

    # If S3 object_name was not specified, use file_name
    if object_name is None:
        object_name = file_path

    # Upload the file
    try:
        s3.upload_file(file_path, bucket_name, object_name)
    except FileNotFoundError:
        print("The file was not found")
        return False
    except NoCredentialsError:
        print("Credentials not available")
        return False

    return True

def download_file_from_s3(file_name, bucket_name, save_as):
    """Download file from an S3 bucket

    :param file_name: File to download
    :param bucket_name: Bucket to download from
    :param save_as: The path and file name to save the file
    """
    s3 = create_s3_client()
    if not s3:
        return False

    try:
        s3.download_file(bucket_name, file_name, save_as)
    except botocore.exceptions.ClientError as e:
        if e.response['Error']['Code'] == "404":
            print("The object does not exist.")
        else:
            raise

def list_objects_in_bucket(bucket_name, prefix):
    """List all objects in an S3 bucket

    :param bucket_name: Name of the S3 bucket
    :param prefix: Path in the S3 bucket
    """
    s3 = create_s3_client()
    if not s3:
        return None

    try:
        objects = s3.list_objects(Bucket=bucket_name, Prefix=prefix)
    except botocore.exceptions.ClientError as e:
        print(e.response['Error']['Message'])
        return None

    return objects

def delete_object_from_bucket(bucket_name, object_name):
    """Delete an object from an S3 bucket

    :param bucket_name: Name of the Bucket
    :param object_name: Name of the object
    """
    s3 = create_s3_client()
    if not s3:
        return False

    try:
        s3.delete_object(Bucket=bucket_name, Key=object_name)
    except botocore.exceptions.ClientError as e:
        if e.response['Error']['Code'] == "NoSuchKey":
            print("The Object does not exist.")
        else:
