import Foundation

class Solution {
    static func findMax(_ words: [String]) -> String {
        guard !words.isEmpty else {
            fatalError("List is empty or null")
        }

        let sortedWords = words.sorted { (s1, s2) -> Bool in
            let distinctCount1 = Set(s1).count
            let distinctCount2 = Set(s2).count
            if distinctCount1 != distinctCount2 {
                return distinctCount2 < distinctCount1
            }
            return words.firstIndex(of: s1)! < words.firstIndex(of: s2)!
        }

        return sortedWords[0]
    }
}

